import{_ as h,o as t,c as i,a5 as c}from"./chunks/framework.Bf1r8NYr.js";const p=JSON.parse('{"title":"HOÀN THÀNH KHÓA HỌC: QUIZ TỔNG HỢP WORKFLOW & BÀI TẬP CAPSTONE","description":"","frontmatter":{},"headers":[],"relativePath":"course/book/ch07.md","filePath":"course/book/ch07.md"}'),g={name:"course/book/ch07.md"};function l(a,n,o,u,r,s){return t(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="hoan-thanh-khoa-hoc-quiz-tong-hop-workflow-bai-tap-capstone" tabindex="-1">HOÀN THÀNH KHÓA HỌC: QUIZ TỔNG HỢP WORKFLOW &amp; BÀI TẬP CAPSTONE <a class="header-anchor" href="#hoan-thanh-khoa-hoc-quiz-tong-hop-workflow-bai-tap-capstone" aria-label="Permalink to &quot;HOÀN THÀNH KHÓA HỌC: QUIZ TỔNG HỢP WORKFLOW &amp; BÀI TẬP CAPSTONE&quot;">​</a></h1><blockquote><p><strong>Phần kết thúc:</strong> Khóa học Quản lý dữ liệu nghiên cứu y sinh (Biomedical RDM)<br><strong>Nội dung:</strong> Quiz Tổng hợp 10 câu + Bài tập Capstone tự đánh giá + Bảng tự nghiệm thu hoàn thành khóa học<br><strong>Thời gian gợi ý:</strong> 45–60 phút cho quiz + trang hoàn thành; toàn khóa khoảng 4–6 giờ đọc + quiz hoặc 9–12 giờ nếu làm đủ lab và capstone <strong>Nguyên tắc:</strong> Tự học, tự đánh giá, không chấm điểm, không nộp bài.</p></blockquote><hr><h2 id="phan-1-quiz-tong-hop-workflow-10-cau-hoi-tu-đanh-gia" tabindex="-1">PHẦN 1. QUIZ TỔNG HỢP WORKFLOW (10 CÂU HỎI TỰ ĐÁNH GIÁ) <a class="header-anchor" href="#phan-1-quiz-tong-hop-workflow-10-cau-hoi-tu-đanh-gia" aria-label="Permalink to &quot;PHẦN 1. QUIZ TỔNG HỢP WORKFLOW (10 CÂU HỎI TỰ ĐÁNH GIÁ)&quot;">​</a></h2><p>Bài quiz này kiểm tra sự liên kết xuyên suốt quy trình 7 giai đoạn của dữ liệu y sinh. Hãy tự trả lời trước khi xem đáp án và giải thích ngắn bên dưới mỗi câu:</p><hr><p><strong>Q1.</strong> Sắp xếp đúng thứ tự workflow: (a) Chuẩn hóa, (b) Thiết kế &amp; DMP, (c) Kết thúc/lưu trữ, (d) Thu thập, (e) FAIR &amp; chia sẻ.</p><ul><li>A. b → d → a → e → c, theo tiến trình từ thiết kế đến lưu trữ.</li><li>B. d → b → a → c → e, bắt đầu bằng thu thập trước khi hoàn thiện kế hoạch.</li><li>C. b → a → d → e → c, đặt chuẩn hóa sớm hơn thu thập dữ liệu.</li><li>D. a → b → d → e → c, đặt chuẩn hóa trước phần thiết kế.</li><li><strong>Đáp án: A.</strong></li><li><strong>Giải thích:</strong> Workflow bắt đầu ở thiết kế và DMP, rồi thu thập, chuẩn hóa, FAIR/chia sẻ và kết thúc bằng lưu trữ hoặc hủy an toàn.</li></ul><p><strong>Q2.</strong> Một nghiên cứu không viết DMP, thu thập xong mới nghĩ đến việc chia sẻ dữ liệu. Hậu quả nào có khả năng xảy ra nhất?</p><ul><li>A. Có thể mất thêm thời gian, nhưng nhiều quyết định quản trị khác vẫn giữ nguyên.</li><li>B. Thiếu metadata và biến không thống nhất, làm khó phê duyệt chia sẻ.</li><li>C. Có ít hậu quả vì quyết định chia sẻ có thể đưa ra ở cuối nghiên cứu.</li><li>D. Dữ liệu tự động trở nên FAIR vì đã được thu thập đầy đủ trong nghiên cứu.</li><li><strong>Đáp án: B.</strong></li><li><strong>Giải thích:</strong> Quyết định thượng nguồn bị bỏ qua có thể làm thiếu metadata, không nhất quán biến và hạn chế khả năng chia sẻ về sau.</li></ul><p><strong>Q3.</strong> Bệnh viện A dùng FHIR để gửi dữ liệu cho bệnh viện B, rồi cả hai cùng phân tích trên OMOP CDM. Nhận định nào đúng?</p><ul><li>A. Phải chuyển sang CDISC trước, dù mục tiêu là trao đổi rồi phân tích quan sát.</li><li>B. Dùng thừa chuẩn; một chuẩn thường đủ cho cả trao đổi và phân tích.</li><li>C. Đúng vai trò: FHIR để trao đổi, OMOP để phân tích.</li><li>D. FHIR và OMOP thường khó dùng chung trong một quy trình liên cơ sở.</li><li><strong>Đáp án: C.</strong></li><li><strong>Giải thích:</strong> FHIR phục vụ trao đổi dữ liệu; OMOP phục vụ chuẩn hóa và phân tích dữ liệu quan sát.</li></ul><p><strong>Q4.</strong> Dữ liệu khuyết vì bệnh nhân nặng không lấy được mẫu xét nghiệm. Cách xử lý đúng nhất là gì?</p><ul><li>A. Xóa toàn bộ bệnh nhân đó để bộ dữ liệu không còn ô khuyết.</li><li>B. Bỏ qua và không ghi lại nguyên nhân vì mẫu xét nghiệm chưa từng được lấy.</li><li>C. Điền giá trị trung bình cho nhiều bệnh nhân để giữ kích thước mẫu.</li><li>D. Xem xét MNAR, ghi giả định, chọn phương pháp và phân tích độ nhạy.</li><li><strong>Đáp án: D.</strong></li><li><strong>Giải thích:</strong> Cơ chế khuyết có thể liên quan đến mức độ bệnh; cần ghi giả định, chọn phương pháp phù hợp và kiểm tra độ nhạy.</li></ul><p><strong>Q5.</strong> Khi xử lý dữ liệu cá nhân trong nghiên cứu, nguyên tắc nào phù hợp nhất?</p><ul><li>A. Chủ yếu áp dụng văn bản có tại thời điểm viết đề cương, ít rà soát về sau.</li><li>B. Có thể bỏ qua ngày hiệu lực nếu tên văn bản đã ghi trong DMP của nghiên cứu.</li><li>C. Đối chiếu văn bản hiện hành và ngày hiệu lực áp dụng cho bối cảnh nghiên cứu.</li><li>D. Chủ yếu tuân theo chính sách phần mềm thu thập dữ liệu, ít căn cứ khác.</li><li><strong>Đáp án: C.</strong> Tên văn bản không đủ để xác định nghĩa vụ; cần kiểm tra văn bản hiện hành, ngày hiệu lực và phạm vi áp dụng.</li></ul><p><strong>Q6.</strong> Một dataset đạt k-anonymity với k=5. Điều này đảm bảo điều gì?</p><ul><li>A. Dữ liệu đã được mã hóa và nhiều khóa liên kết đã bị loại bỏ.</li><li>B. Mỗi quasi-identifier xuất hiện ít nhất 5 lần; vẫn còn nguy cơ từ thông tin nền.</li><li>C. Không ai có thể tái định danh bằng bất kỳ cách nào, kể cả liên kết nguồn khác.</li><li>D. Dữ liệu được phép công khai mà không cần xét duyệt hoặc kiểm soát truy cập.</li><li><strong>Đáp án: B.</strong></li><li><strong>Giải thích:</strong> k-anonymity giới hạn liên kết trực tiếp, nhưng không loại bỏ mọi nguy cơ tái định danh hoặc suy luận thuộc tính nhạy cảm.</li></ul><p><strong>Q7.</strong> Nhận định nào mô tả đầy đủ hơn yêu cầu để dữ liệu y sinh sẵn sàng cho AI?</p><ul><li>A. Dữ liệu cần lớn, sạch và ở định dạng bảng tính phổ biến để mô hình đọc được.</li><li>B. Dữ liệu chủ yếu cần có nhiều biến và ít ô trống, không cần provenance.</li><li>C. AI-ready cần FAIR, provenance, giải trình, quản trị và khả năng tính toán.</li><li>D. Dữ liệu nên được giữ kín để tránh rủi ro, không cần khả năng tái sử dụng.</li><li><strong>Đáp án: C.</strong> AI-ready là yêu cầu đa chiều về khả năng tìm thấy, hiểu, giải trình, quản trị và tính toán, không chỉ là dung lượng hoặc độ sạch.</li></ul><p><strong>Q8.</strong> Nghiên cứu kết thúc, nhóm xóa file dữ liệu bằng cách xóa thông thường trong hệ điều hành. Đủ chưa?</p><ul><li>A. Chưa chắc; xóa thông thường chưa đồng nghĩa khử hoặc hủy an toàn.</li><li>B. Đủ trong nhiều trường hợp vì tệp không còn hiển thị trong thư mục.</li><li>C. Không cần hủy, cứ giữ dữ liệu mãi mãi bất kể chính sách lưu giữ.</li><li>D. Cần quan tâm khi dataset có kích thước lớn hoặc nhiều tệp.</li><li><strong>Đáp án: A.</strong> Cần có quy trình khử hoặc hủy phù hợp với loại lưu trữ, chính sách và yêu cầu áp dụng; xóa thông thường chưa đủ để kết luận an toàn.</li></ul><p><strong>Q9.</strong> Trong workflow FAIRification 7 bước, đánh giá FAIR được dùng như thế nào?</p><ul><li>A. Đánh giá bước 1 để tìm khoảng cách và bước 7 để kiểm tra cải thiện.</li><li>B. Thường đánh giá một lần ở bước 7, sau khi đã hoàn tất nhiều thay đổi.</li><li>C. Chủ yếu đánh giá khi dữ liệu được công khai và không còn hạn chế.</li><li>D. Đánh giá FAIR thay thế cho việc lập kế hoạch và quản trị ở bước 1.</li><li><strong>Đáp án: A.</strong> Đánh giá ban đầu định hướng kế hoạch, còn đánh giá lại ở bước 7 kiểm tra mức cải thiện và kết quả đạt được.</li></ul><p><strong>Q10.</strong> Một học viên nói: “Dữ liệu của tôi đã FAIR nên tôi công khai toàn bộ lên mạng.” Sai ở đâu?</p><ul><li>A. Không sai, vì nhiều dữ liệu FAIR được công khai trên mạng.</li><li>B. FAIR chủ yếu áp dụng cho dữ liệu mở và không áp dụng cho dữ liệu sức khỏe.</li><li>C. Phải công khai mới gọi là FAIR, bất kể ràng buộc đạo đức hay pháp lý.</li><li>D. FAIR không đồng nghĩa mở hết; dữ liệu sức khỏe có thể kiểm soát truy cập.</li><li><strong>Đáp án: D.</strong> FAIR yêu cầu khả năng tìm thấy, truy cập được theo điều kiện, liên thông và tái sử dụng; không buộc dữ liệu nhạy cảm phải mở công khai.</li></ul><p><strong>Cách tính điểm:</strong> mỗi câu 1 điểm. Tổng số câu quiz = tổng số câu trong các chương (N1+…+N6) + 10 câu của quiz tổng hợp; mục tiêu tự đánh giá là đúng ≥ 70% tổng số câu và đúng ≥ 2/3 câu Q1–Q3 của quiz tổng hợp. Đây là tự đánh giá, không ai ghi lại kết quả; làm lại không giới hạn.</p><hr><h2 id="phan-2-bai-tap-capstone-tu-đanh-gia-capstone-self-assessment" tabindex="-1">PHẦN 2. BÀI TẬP CAPSTONE TỰ ĐÁNH GIÁ (CAPSTONE SELF-ASSESSMENT) <a class="header-anchor" href="#phan-2-bai-tap-capstone-tu-đanh-gia-capstone-self-assessment" aria-label="Permalink to &quot;PHẦN 2. BÀI TẬP CAPSTONE TỰ ĐÁNH GIÁ (CAPSTONE SELF-ASSESSMENT)&quot;">​</a></h2><h3 id="tinh-huong-gia-đinh" tabindex="-1">Tình huống giả định: <a class="header-anchor" href="#tinh-huong-gia-đinh" aria-label="Permalink to &quot;Tình huống giả định:&quot;">​</a></h3><p>Bạn đóng vai trò là <strong>Research Data Steward</strong> hỗ trợ nhóm nghiên cứu thực hiện đề tài:<br><em>&quot;Nghiên cứu thí điểm đa phương thức hỗ trợ theo dõi một bệnh lý nội tiết tại một cơ sở đào tạo y khoa&quot;</em>.</p><ul><li><strong>Quy mô dự kiến:</strong> một tập dữ liệu nhỏ giả định gồm dữ liệu lâm sàng, kết quả xét nghiệm và bảng câu hỏi; không dùng dữ liệu người bệnh thật.</li></ul><h3 id="nhiem-vu-thuc-hanh-tu-do-cua-ban" tabindex="-1">Nhiệm vụ thực hành tự do của bạn: <a class="header-anchor" href="#nhiem-vu-thuc-hanh-tu-do-cua-ban" aria-label="Permalink to &quot;Nhiệm vụ thực hành tự do của bạn:&quot;">​</a></h3><p>Hãy tự soạn thảo một bộ hồ sơ <strong>RDM Package</strong> gồm 4 tài liệu sau (bằng tệp Markdown hoặc Word):</p><ol><li><strong>Bản Kế hoạch Quản lý và Chia sẻ Dữ liệu (DMSP):</strong> dùng mẫu NIH hiện hành (7 yếu tố) hoặc Horizon Europe, tham khảo <code>/course/book/appendices/funder-templates</code>, và chỉ định rõ phương án lưu trữ/chia sẻ.</li><li><strong>Từ điển Dữ liệu (Data Dictionary):</strong> Định nghĩa ít nhất 10 biến số lâm sàng, chuẩn hóa định dạng, khoảng giá trị hợp lệ, và mã hóa từ vựng chuẩn (SNOMED CT, LOINC, ICD-10).</li><li><strong>Kế hoạch Bảo mật &amp; Khử định danh:</strong> Mô tả phương án loại bỏ các định danh HIPAA Safe Harbor, quy trình dịch chuyển ngày (Date Shifting) bảo toàn khoảng thời gian, và các bước xây dựng Hồ sơ Đánh giá tác động xử lý dữ liệu cá nhân (DPIA) theo Luật 91/2025/QH15 và Nghị định 356/2025/NĐ-CP.</li><li><strong>Kế hoạch FAIR &amp; AI-Ready:</strong> Mô tả phương án đóng gói dữ liệu kèm siêu dữ liệu mô tả nguồn gốc sâu (Deep Provenance) theo 7 tiêu chí Bridge2AI và lựa chọn giấy phép chia sẻ (CC BY 4.0 / Open Data License).</li></ol><hr><h3 id="bang-checklist-tu-đanh-gia-bai-tap-capstone-1-trang" tabindex="-1">Bảng Checklist Tự Đánh giá Bài tập Capstone (1 Trang) <a class="header-anchor" href="#bang-checklist-tu-đanh-gia-bai-tap-capstone-1-trang" aria-label="Permalink to &quot;Bảng Checklist Tự Đánh giá Bài tập Capstone (1 Trang)&quot;">​</a></h3><p><em>(Hãy tự tích chọn vào các ô dưới đây khi bạn hoàn thành sản phẩm của mình)</em></p><ul><li>[ ] <strong>Mục 1 — Bản DMSP theo mẫu đã chọn:</strong><ul><li>[ ] Nêu rõ loại dữ liệu (bảng lâm sàng, ảnh tổn thương sẩn phù có thước đo chuẩn, kết quả xét nghiệm).</li><li>[ ] Công cụ và mã nguồn phân tích được xác định (Python, R, REDCap) kèm cam kết công khai GitHub/Zenodo.</li><li>[ ] Chuẩn dữ liệu được áp dụng (OMOP CDM v5.4, SNOMED CT, LOINC).</li><li>[ ] Tên kho lưu trữ dữ liệu mở được chỉ định cụ thể (Zenodo Sandbox / Zenodo).</li><li>[ ] Nêu rõ người chịu trách nhiệm giám sát (PI và Data Steward).</li></ul></li><li>[ ] <strong>Mục 2 — Từ điển Dữ liệu (Data Dictionary):</strong><ul><li>[ ] Có đầy đủ tên biến, nhãn hiển thị, kiểu dữ liệu, đơn vị đo lường và danh mục mã hóa chuẩn.</li><li>[ ] Có quy tắc kiểm tra logic (Range check, Validation rule) để chặn lỗi nhập liệu ngay tại khâu thu thập.</li></ul></li><li>[ ] <strong>Mục 3 — Bảo mật &amp; Khử định danh:</strong><ul><li>[ ] Xem xét 18 nhóm định danh theo Safe Harbor và ghi rõ giới hạn của phương pháp.</li><li>[ ] Đối với dữ liệu ngày tháng: ghi rõ Date Shifting không phải Safe Harbor; nếu giữ ngày cần căn cứ khác (Expert Determination hoặc căn cứ pháp lý tương ứng), tham khảo ch05.</li><li>[ ] Dẫn chiếu đúng khung pháp lý hiện hành của Việt Nam: Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 và Nghị định 356/2025/NĐ-CP (thay thế Nghị định 13/2023/NĐ-CP).</li></ul></li><li>[ ] <strong>Mục 4 — FAIR &amp; Chuẩn AI-Ready:</strong><ul><li>[ ] Bộ dữ liệu có tệp <code>README.md</code> mô tả đặc tính nhân khẩu học và nguồn gốc sâu (thiết bị chụp ảnh, ánh sáng chuẩn, quy trình tiền xử lý).</li><li>[ ] Lựa chọn giấy phép chia sẻ chuẩn mực (ví dụ: CC BY 4.0 cho dữ liệu tổng hợp / DUA cho dữ liệu truy cập có kiểm soát).</li></ul></li></ul><hr><h2 id="phan-3-bang-tu-nghiem-thu-hoan-thanh-khoa-hoc" tabindex="-1">PHẦN 3. BẢNG TỰ NGHIỆM THU HOÀN THÀNH KHÓA HỌC <a class="header-anchor" href="#phan-3-bang-tu-nghiem-thu-hoan-thanh-khoa-hoc" aria-label="Permalink to &quot;PHẦN 3. BẢNG TỰ NGHIỆM THU HOÀN THÀNH KHÓA HỌC&quot;">​</a></h2><p>Chúc mừng bạn đã hoàn thành hành trình học tập nghiên cứu dữ liệu y sinh! Hãy tự đối chiếu các tiêu chí dưới đây để ghi nhận kết quả cá nhân của bạn:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Hạng mục học tập</th><th style="text-align:left;">Tiêu chí hoàn thành tự đánh giá</th><th style="text-align:center;">Tự xác nhận</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Đọc hiểu lý thuyết</strong></td><td style="text-align:left;">Đã hoàn thành việc đọc toàn bộ Module 0 đến Module 6</td><td style="text-align:center;">[ ] Đã hoàn thành</td></tr><tr><td style="text-align:left;"><strong>Quiz theo chương (M1–M6)</strong></td><td style="text-align:left;">Làm quiz trong từng chương; tổng số câu theo chương được cộng với 10 câu quiz tổng hợp</td><td style="text-align:center;">[ ] Tự đối chiếu</td></tr><tr><td style="text-align:left;"><strong>Quiz Tổng hợp Workflow</strong></td><td style="text-align:left;">Tự đánh giá đúng <strong>≥ 70% tổng số câu</strong> và <strong>≥ 2/3 câu Q1–Q3</strong>; không ai ghi lại kết quả</td><td style="text-align:center;">[ ] Tự đối chiếu</td></tr><tr><td style="text-align:left;"><strong>Thực hành kỹ năng (Labs)</strong></td><td style="text-align:left;">Đã trải nghiệm các bài lab tự chọn (tối thiểu Lab 1 về DMPTool và Lab 2 về REDCap)</td><td style="text-align:center;">[ ] Đã hoàn thành</td></tr><tr><td style="text-align:left;"><strong>Bài tập Capstone</strong></td><td style="text-align:left;">Đã tự thiết kế và đối chiếu đạt yêu cầu theo Bảng Checklist Capstone 1 trang</td><td style="text-align:center;">[ ] Đã hoàn thành</td></tr></tbody></table><blockquote><p><strong>Lời kết từ nhóm biên soạn:</strong> Quản lý dữ liệu y sinh không phải là một công việc hành chính đơn thuần, mà là nền móng của sự liêm chính khoa học và đạo đức nghiên cứu y học. Kỹ năng bạn lĩnh hội từ khóa học này sẽ đồng hành cùng bạn trong từng công trình nghiên cứu, giúp các phát hiện khoa học của bạn luôn đáng tin cậy, có thể tái lập và đóng góp giá trị lâu dài cho sức khỏe cộng đồng.</p></blockquote>',44)])])}const d=h(g,[["render",l]]);export{p as __pageData,d as default};
